//! The codecs against Core's own (`tests/data/codec/`, regenerated by
//! `contrib/node/ev2a-codec-probe/regen.py`, which links Core's v24 codecs; each file's header
//! records the probe's MANIFEST), plus round trips over our records.

use std::collections::BTreeMap;

use super::*;
use crate::testkit::{dmn, dmn_with};
use crate::{MnListError, MnType, SameRecord};
use dash_types::codec::DecodeError;

const LISTS: &str = include_str!("../../tests/data/codec/lists.txt");
const DIFFS: &str = include_str!("../../tests/data/codec/diffs.txt");
const APPLY: &str = include_str!("../../tests/data/codec/apply.txt");
const VERDICTS: &str = include_str!("../../tests/data/codec/verdicts.txt");

const NET: ContextFreeNetInfo = ContextFreeNetInfo;

fn unhex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd hex length");
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex")).collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn sha256d_hex(bytes: &[u8]) -> String {
    let mut hasher = HashWriter::new();
    hasher.write(bytes);
    hex(&hasher.finish())
}

fn records(text: &str) -> impl Iterator<Item = Vec<&str>> {
    text.lines().filter(|l| !l.starts_with('#') && !l.is_empty()).map(|l| l.split(' ').collect())
}

/// Core's `what()` without the `: iostream error` that `std::ios_base::failure` appends.
fn core_text(fields: &[&str]) -> String {
    let text = fields.join(" ");
    text.strip_suffix(": iostream error").unwrap_or(&text).to_string()
}

/// A text up to its first rendered value (`=…`): Core renders key ids as Base58 addresses and
/// keys in its own string form, which the pure crate does not (D3), and names the first missing
/// id in a salted-hash order (D13).
fn class(text: &str) -> &str {
    text.split('=').next().unwrap_or(text)
}

/// Lists by name: (canonical, hash, evodb, evodb after Core's reload).
fn lists() -> BTreeMap<String, [Vec<u8>; 4]> {
    records(LISTS)
        .map(|f| (f[1].to_string(), [unhex(f[2]), unhex(f[3]), unhex(f[4]), unhex(f[5])]))
        .collect()
}

fn diffs() -> BTreeMap<String, [Vec<u8>; 2]> {
    records(DIFFS).map(|f| (f[1].to_string(), [unhex(f[2]), unhex(f[3])])).collect()
}

fn decode_list(bytes: &[u8]) -> MnList {
    let mut input = bytes;
    let list = decode_canonical_list(&mut input, &NET).expect("Core accepted it");
    assert!(input.is_empty());
    list
}

fn canonical(list: &MnList) -> Vec<u8> {
    let mut out = Vec::new();
    encode_canonical_list_unvalidated(list, &mut out);
    out
}

/// The proTxHashes of an evodb list in the file's order.
fn evodb_order(bytes: &[u8]) -> Vec<ProTxHash> {
    let mut input = &bytes[40..];
    let n = read_compact_size(&mut input, true).expect("count");
    (0..n).map(|_| Reader::new(&mut input, None).dmn().expect("entry").pro_tx_hash).collect()
}

#[test]
fn lists_match_cores_bytes_hash_and_reload_order() {
    let lists = lists();
    assert_eq!(lists.len(), 7);
    for (name, [bytes, hash, evodb, reloaded]) in &lists {
        let list = decode_list(bytes);
        assert_eq!(canonical(&list), *bytes, "{name}: re-encoding");
        assert_eq!(hex(canonical_mn_list_hash(&list).as_bytes()), hex(hash), "{name}: hash");
        let mut validated = Vec::new();
        encode_canonical_list(&list, &NET, &mut validated).expect("valid");
        assert_eq!(validated, *bytes, "{name}: storage encoder");
        list.check_invariants().expect("invariants");

        // The evodb reader: the same content, and Core's order after a reload (quirk 41: AddMN
        // in file order rebuilds every collision bucket newest first).
        let imported = core_disk::decode_list_s3(&mut evodb.as_slice()).expect("evodb list");
        assert_eq!(canonical(&imported), *bytes, "{name}: evodb content");
        assert!(imported.is_equal(&list) && list.is_equal(&imported), "{name}: IsEqual");
        assert_eq!(
            &*imported.core_order(),
            evodb_order(reloaded).as_slice(),
            "{name}: reload order"
        );
        let again = core_disk::decode_list_s3(&mut reloaded.as_slice()).expect("reloaded list");
        assert_eq!(canonical(&again), *bytes, "{name}: reloaded content");
    }
    // The fixtures hold a collision bucket that a reload reverses.
    let [_, _, evodb, reloaded] = &lists["collide"];
    assert_ne!(evodb_order(evodb), evodb_order(reloaded));
}

#[test]
fn diffs_match_cores_bytes() {
    let diffs = diffs();
    assert_eq!(diffs.len(), 18);
    for (name, [bytes, evodb]) in &diffs {
        let mut input = bytes.as_slice();
        let diff =
            decode_canonical_diff(&mut input, &mut { usize::MAX }, &NET).expect("Core's diff");
        assert!(input.is_empty());
        let mut out = Vec::new();
        encode_canonical_diff(&diff, &mut out);
        assert_eq!(out, *bytes, "{name}: re-encoding");
        let imported = core_disk::decode_diff_d4(&mut evodb.as_slice()).expect("evodb diff");
        let mut out = Vec::new();
        encode_canonical_diff(&imported, &mut out);
        assert_eq!(out, *bytes, "{name}: evodb diff");
    }
}

#[test]
fn diffs_are_cores_build_diff_and_apply_as_cores() {
    let (lists, diffs) = (lists(), diffs());
    let mut applied = 0;
    for f in records(APPLY) {
        let (name, block, height) = (f[1], f[2], f[3].parse::<i32>().expect("height"));
        let (from, to) = name.split_once('>').expect("from>to");
        let (a, b) = (decode_list(&lists[from][0]), decode_list(&lists[to][0]));
        // Our diff_to is Core's BuildDiff.
        let mut built = Vec::new();
        encode_canonical_diff(&a.diff_to(&b), &mut built);
        assert_eq!(built, diffs[name][0], "{name}: diff_to");

        let diff = decode_canonical_diff(&mut diffs[name][0].as_slice(), &mut { usize::MAX }, &NET)
            .expect("Core's diff");
        let mut list = a.clone();
        let block = BlockHash::from(<[u8; 32]>::try_from(unhex(block)).expect("hash"));
        match (list.apply_diff(block, height, &diff), f[4]) {
            (Ok(()), "ok") => {
                assert_eq!(hex(canonical_mn_list_hash(&list).as_bytes()), f[5], "{name}: applied");
                assert!(list.is_equal(&b), "{name}: IsEqual to the target");
                applied += 1;
            }
            (Err(e), "err") => {
                assert_eq!(class(&e.to_string()), class(&core_text(&f[5..])), "{name}")
            }
            (ours, _) => panic!("{name}: ours {ours:?}, Core {}", f[4..].join(" ")),
        }
    }
    assert_eq!(applied, 16);
}

/// Texts the canonical readers own, which must be Core's exactly; others (end of data,
/// CompactSize range) only need to be refusals.
fn snapshot_text(text: &str) -> bool {
    [
        "noncanonical",
        "invalid canonical",
        "negative canonical",
        "canonical MN",
        "oversized",
        "historical",
        "Invalid data",
    ]
    .iter()
    .any(|p| text.starts_with(p))
}

#[test]
fn readers_give_cores_verdicts_on_mutated_bytes() {
    let (mut accepted, mut refused, mut netinfo) = (0, 0, 0);
    for f in records(VERDICTS) {
        let bytes = unhex(f[1]);
        let mut input = bytes.as_slice();
        let ours = match f[0] {
            "canon" => decode_canonical_list(&mut input, &NET)
                .map(|list| hex(canonical_mn_list_hash(&list).as_bytes())),
            "cdiff" => decode_canonical_diff(&mut input, &mut { usize::MAX }, &NET).map(|diff| {
                let mut out = Vec::new();
                encode_canonical_diff(&diff, &mut out);
                sha256d_hex(&out)
            }),
            other => panic!("unknown vector {other}"),
        };
        let ours = ours.and_then(|v| {
            if input.is_empty() {
                Ok(v)
            } else {
                Err(CodecError::new("trailing bytes"))
            }
        });
        let core = core_text(&f[3..]);
        match (&ours, f[2]) {
            // Core's address validation is EV1's (D12): where Core refuses an entry's network
            // info, the context-free stand-in may accept it and stop later, or not at all. Core
            // gives a diff addition's order violation the same text, so a refusal with Core's
            // text is still compared below.
            _ if (core == "invalid canonical MN network info"
                || core == "noncanonical canonical MN-diff addition")
                && !matches!(&ours, Err(e) if e.0 == core) =>
            {
                netinfo += 1
            }
            (Ok(v), "ok") => {
                assert_eq!(*v, f[3], "{} {}", f[0], f[1]);
                accepted += 1;
            }
            (Err(e), "err") => {
                if snapshot_text(&core) {
                    assert_eq!(class(&e.0), class(&core), "{} {}", f[0], f[1]);
                }
                refused += 1;
            }
            _ => panic!("{} {}: ours {ours:?}, Core {core}", f[0], f[1]),
        }
    }
    assert!(accepted > 100 && refused > 150, "accepted {accepted}, refused {refused}");
    assert!(netinfo <= 12, "{netinfo} network-info verdicts differ");
}

// ----------------------------------------------------------------------------------------------
// The nested CompactSize budget (EV2a fix r1, R1-M1): Core charges each length before it reads
// what the length sizes, in network info and in payout and share scripts.

const BUDGET: &str = include_str!("../../tests/data/codec/budget.txt");

/// The base entry's network info as Core writes it: version 1, one Core P2P group holding the
/// IPv4 service 1.2.3.4:9999. The budget it uses: 2 (one group, one entry; Core's budget does
/// not see the address length).
const BASE_NET_INFO: &[u8] = &[1, 1, 0, 1, 1, 1, 4, 1, 2, 3, 4, 0x27, 0x0f];
/// One `OP_TRUE` payout of 10000.
const BASE_PAYOUTS: &[u8] = &[1, 1, 0x51, 0x10, 0x27];
const NO_SHARES: &[u8] = &[0];
/// `NetInfoEntry`'s invalid tag: Core reads nothing past it and charges nothing.
const INVALID_ENTRY: u8 = 0xff;

fn compact(n: u64) -> Vec<u8> {
    let mut out = Vec::new();
    write_compact_size(n, &mut out);
    out
}

/// A one-entry list whose version-3 entry has `net_info`, `payouts` and `shares` spliced in
/// for the base fields.
fn with_fields(net_info: &[u8], payouts: &[u8], shares: &[u8]) -> Vec<u8> {
    let dmn = dmn_with(1, MnType::Regular, |_, cold| {
        cold.version = EXT_ADDR;
        cold.pub_key_operator =
            crate::testkit::operator_key(1, dash_pkc::bls::BlsSchemeKind::Basic);
        cold.net_info = Arc::new(NetInfo::Extended(
            NetInfoV2::decode(&mut &BASE_NET_INFO[..]).expect("network info"),
        ));
        cold.payouts = vec![PayoutShare::decode(&mut &BASE_PAYOUTS[1..]).expect("a payout")];
    });
    let mut list = MnList::new(BlockHash::from([7; 32]), 2_300_000, 2);
    list.try_add(dmn, false).expect("in Core's state domain");
    let base = canonical(&list);
    let fields = [BASE_NET_INFO, BASE_PAYOUTS, NO_SHARES].concat();
    let at = base.windows(fields.len()).position(|w| w == fields).expect("the entry's fields");
    [&base[..at], net_info, payouts, shares, &base[at + fields.len()..]].concat()
}

/// Network info of `groups`, each `(purpose, entry count, entry bytes)`.
fn net_info(groups: &[(u8, u64, Vec<u8>)]) -> Vec<u8> {
    let mut out = vec![1];
    out.extend(compact(groups.len() as u64));
    for (purpose, count, entries) in groups {
        out.push(*purpose);
        out.extend(compact(*count));
        out.extend(entries);
    }
    out
}

/// The budget cases, each exhausting the budget early in one nested field (or at its edge).
/// Lengths whose bytes would follow are left out: Core refuses before it reads them.
fn budget_cases() -> Vec<(&'static str, Vec<u8>)> {
    let service = &BASE_NET_INFO[4..];
    let invalid = |n: usize| vec![INVALID_ENTRY; n];
    let amount = [0u8; 8];
    vec![
        ("base", with_fields(BASE_NET_INFO, BASE_PAYOUTS, NO_SHARES)),
        // 2 + 9,999 > 10,000.
        ("payout-count", with_fields(BASE_NET_INFO, &compact(9_999), &[])),
        // 2 + 1, then 9,998 > 9,997.
        ("payout-script", with_fields(BASE_NET_INFO, &[compact(1), compact(9_998)].concat(), &[])),
        // 9,997 fits; the script's bytes are missing.
        (
            "payout-script-at-budget",
            with_fields(BASE_NET_INFO, &[compact(1), compact(9_997)].concat(), &[]),
        ),
        // 2 + 1 + 9,997 is the whole budget, which a charged address length would exceed.
        (
            "payout-script-uses-the-budget",
            with_fields(
                BASE_NET_INFO,
                &[&compact(1)[..], &compact(9_997), &[0x61; 9_997], &[0x10, 0x27]].concat(),
                NO_SHARES,
            ),
        ),
        (
            "share-refund-script",
            with_fields(BASE_NET_INFO, &[0], &[&compact(1)[..], &amount, &compact(9_998)].concat()),
        ),
        (
            "share-reward-script",
            with_fields(
                BASE_NET_INFO,
                &[0],
                &[&compact(1)[..], &amount, &compact(0), &compact(9_998)].concat(),
            ),
        ),
        ("group-count", with_fields(&[&[1u8][..], &compact(10_001)].concat(), &[], &[])),
        ("entry-count", with_fields(&net_info(&[(0, 10_000, Vec::new())]), &[], &[])),
        // 2, then a name of 9,999 > 9,998, before the name's own limit is checked.
        (
            "domain-length",
            with_fields(&net_info(&[(0, 1, [&[2u8][..], &compact(9_999)].concat())]), &[], &[]),
        ),
        // Within the budget and over `DOMAIN_MAX_LEN`.
        (
            "domain-length-over-limit",
            with_fields(&net_info(&[(0, 1, [&[2u8][..], &compact(254)].concat())]), &[], &[]),
        ),
        // A repeated purpose fails the read before its group's count is charged (CE4-01; rc.3
        // charged 2 + 5,000 + 5,000 > 10,000).
        (
            "duplicate-group",
            with_fields(&net_info(&[(0, 5_000, invalid(5_000)), (0, 5_000, Vec::new())]), &[], &[]),
        ),
        // Within the budget: refused at the repeated purpose.
        (
            "duplicate-group-in-budget",
            with_fields(
                &net_info(&[(0, 1, service.to_vec()), (0, 1, service.to_vec())]),
                BASE_PAYOUTS,
                NO_SHARES,
            ),
        ),
        // A 600-byte address is refused by its size, uncharged: the entry is invalid, and the
        // next group's count fits in 10,000 - (2 + 1), so the reader runs out of data.
        (
            "service-length-over-limit",
            with_fields(
                &[&[1, 2, 0][..], &compact(1), &[1, 1], &compact(600), &[1], &compact(9_398)]
                    .concat(),
                &[],
                &[],
            ),
        ),
    ]
}

/// Prints the cases for the probe; `contrib/node/ev2a-codec-probe/budget.py` writes
/// `tests/data/codec/budget.txt` from them.
#[test]
#[ignore = "writes the probe's input"]
fn print_budget_cases() {
    for (name, bytes) in budget_cases() {
        println!("{name} {}", hex(&bytes));
    }
}

#[test]
fn the_nested_budget_is_charged_as_cores() {
    let cases: BTreeMap<_, _> = budget_cases().into_iter().collect();
    let mut seen = 0;
    for f in records(BUDGET) {
        let (name, bytes) = (f[1], unhex(f[2]));
        assert_eq!(Some(&bytes), cases.get(name), "{name}: budget.txt is stale");
        let mut input = bytes.as_slice();
        let ours = decode_canonical_list(&mut input, &NET)
            .map(|list| hex(canonical_mn_list_hash(&list).as_bytes()));
        let core = core_text(&f[4..]);
        match (&ours, f[3]) {
            (Ok(v), "ok") => assert_eq!(*v, f[4], "{name}"),
            (Err(e), "err") if snapshot_text(&core) => assert_eq!(e.0, core, "{name}"),
            (Err(_), "err") => {}
            _ => panic!("{name}: ours {ours:?}, Core {core}"),
        }
        seen += 1;
    }
    assert_eq!(seen, cases.len(), "budget.txt has every case");
}

// ----------------------------------------------------------------------------------------------
// Our records.

fn sample_lists() -> (MnList, MnList) {
    let mut a = MnList::scratch();
    for n in 1..=6 {
        a.try_add(
            dmn(
                n,
                if n % 2 == 0 {
                    MnType::Evo
                } else {
                    MnType::Regular
                },
            ),
            true,
        )
        .expect("add");
    }
    let a = {
        let mut list = MnList::new(BlockHash::from([1; 32]), 1000, a.total_registered());
        for dmn in a.iter() {
            list.try_add(Arc::clone(dmn), false).expect("add");
        }
        list
    };
    let mut b = a.clone();
    b.apply_diff(BlockHash::from([2; 32]), 1001, &MnListDiff::default()).expect("position");
    let three = b.get(&crate::testkit::pro_tx(3)).cloned().expect("mn 3");
    let mut hot = three.hot;
    hot.last_paid_height = 1001;
    b.update_hot(&three.pro_tx_hash, hot).expect("hot");
    b.remove(&crate::testkit::pro_tx(4)).expect("remove");
    b.try_add(dmn_with(9, MnType::Regular, |_, cold| cold.version = 2), true).expect("add");
    (a, b)
}

#[test]
fn records_round_trip_in_full() {
    let (a, b) = sample_lists();
    let bytes = encode_snapshot_record(&a, &NET).expect("snapshot");
    let DmlRecord::Snapshot(decoded) = decode_record(bytes.as_bytes(), &NET).expect("decode")
    else {
        panic!("not a snapshot")
    };
    assert!((*decoded).same_record(&a));
    assert_eq!(decoded.core_order(), a.core_order());
    assert_eq!(decoded.total_registered(), a.total_registered());

    let record = MnListDiffRecord::build(&a, &b);
    let bytes = encode_diff_record(&record, &NET).expect("diff");
    let DmlRecord::Diff(decoded) = decode_record(bytes.as_bytes(), &NET).expect("decode") else {
        panic!("not a diff")
    };
    assert_eq!(decoded.height, record.height);
    assert_eq!(decoded.total_registered_after, record.total_registered_after);
    assert_eq!(decoded.collision_buckets_after, record.collision_buckets_after);
    assert!(decoded.diff.same_record(&record.diff));
    let mut rebuilt = a.clone();
    rebuilt.apply_record(*b.block_hash(), &decoded).expect("apply");
    assert!(rebuilt.same_record(&b));
    assert_eq!(rebuilt.core_order(), b.core_order());
}

#[test]
fn records_refuse_what_they_cannot_hold() {
    let (a, _) = sample_lists();
    let bytes = encode_snapshot_record(&a, &NET).expect("snapshot");
    let mut trailing = bytes.as_bytes().to_vec();
    trailing.push(0);
    assert_eq!(decode_record(&trailing, &NET).unwrap_err().0, "trailing bytes after a DML record");
    let mut version = bytes.as_bytes().to_vec();
    version[0] = 2;
    assert!(decode_record(&version, &NET).unwrap_err().0.starts_with("unknown DML record version"));
    let mut codec = bytes.as_bytes().to_vec();
    codec[1] = 9;
    assert!(decode_record(&codec, &NET).unwrap_err().0.starts_with("unknown DML codec id 9"));
    // A trailer naming a key the list does not hold.
    let mut out = envelope(CODEC_CANONICAL_LIST, a.height()).expect("envelope");
    encode_canonical_list(&a, &NET, &mut out).expect("list");
    let stranger = crate::testkit::pro_tx(77);
    write_buckets([(stranger.immer_hash(), [stranger, stranger].as_slice())].into_iter(), &mut out);
    assert!(decode_record(&out, &NET).is_err());
    // The pre-DIP3 default list has a hash but no record.
    let default = MnList::default_pre_dip3();
    assert_eq!(encode_snapshot_record(&default, &NET).unwrap_err().0, "negative record height");
    let mut bytes = Vec::new();
    encode_canonical_list_unvalidated(&default, &mut bytes);
    assert_eq!(
        decode_canonical_list(&mut bytes.as_slice(), &NET).unwrap_err().0,
        "negative canonical MN-list height"
    );
}

/// Collision trailers (EV2 §2.9): records of colliding lists round-trip with Core's order; a
/// snapshot's trailer holds every bucket, each with two or more members; a diff's empty sequence
/// cannot drop a bucket the list still has.
#[test]
fn collision_trailers_are_canonical_and_checked() {
    let lists = lists();
    let (a, b) = (decode_list(&lists["collide"][0]), decode_list(&lists["collide2"][0]));
    let snapshot = encode_snapshot_record(&a, &NET).expect("snapshot");
    let DmlRecord::Snapshot(decoded) = decode_record(snapshot.as_bytes(), &NET).expect("decode")
    else {
        panic!("not a snapshot")
    };
    assert_eq!(decoded.core_order(), a.core_order());
    let record = MnListDiffRecord::build(&a, &b);
    let bytes = encode_diff_record(&record, &NET).expect("diff");
    let DmlRecord::Diff(diff) = decode_record(bytes.as_bytes(), &NET).expect("decode") else {
        panic!("not a diff")
    };
    let mut rebuilt = (*decoded).clone();
    rebuilt.apply_record(*b.block_hash(), &diff).expect("apply");
    assert!(rebuilt.is_equal(&b));
    assert_eq!(rebuilt.core_order(), b.core_order());

    let snapshot_with = |buckets: &[(u64, &[ProTxHash])]| {
        let mut out = envelope(CODEC_CANONICAL_LIST, a.height()).expect("envelope");
        encode_canonical_list(&a, &NET, &mut out).expect("list");
        write_buckets(buckets.iter().copied(), &mut out);
        decode_record(&out, &NET).map(|_| ()).unwrap_err().0
    };
    let owned: Vec<(u64, Vec<ProTxHash>)> =
        a.collision_buckets().map(|(h, b)| (h, b.iter().copied().collect())).collect();
    let buckets: Vec<(u64, &[ProTxHash])> = owned.iter().map(|(h, m)| (*h, m.as_slice())).collect();
    let (hash, members) = buckets[0];
    assert_eq!(snapshot_with(&buckets[1..]), "snapshot collision trailer misses a bucket");
    let mut empty = buckets.clone();
    empty[0] = (hash, &[]);
    assert_eq!(snapshot_with(&empty), "snapshot collision trailer bucket with no member");
    let mut one = buckets.clone();
    one[0] = (hash, &members[..1]);
    assert_eq!(snapshot_with(&one), "collision trailer bucket with one member");

    let (kept, _) = b.collision_buckets().next().expect("collide2 has a bucket");
    let forged = MnListDiffRecord {
        collision_buckets_after: vec![(kept, Vec::new())],
        ..record
    };
    let mut target = a.clone();
    assert_eq!(
        target.apply_record(*b.block_hash(), &forged),
        Err(MnListError::BadCollisionTrailer(kept))
    );
}

/// node-fuzz's `apply-*` seeds (mode 5: a snapshot record's length as a little-endian u16, the
/// snapshot record, then a diff record that applies to it) are these Core lists' records.
/// `DASH_DML_WRITE_SEEDS=1` rewrites them.
#[test]
#[allow(clippy::disallowed_methods, reason = "the environment asks the test to rewrite the seeds")]
fn fuzz_apply_seeds_are_current() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../node-fuzz/seeds/dml_codec_roundtrip");
    let lists = lists();
    for (from, to) in [("collide", "collide2"), ("collide2", "collide"), ("mixed", "next")] {
        let (a, b) = (decode_list(&lists[from][0]), decode_list(&lists[to][0]));
        let snapshot = encode_snapshot_record(&a, &NET).expect("snapshot");
        let diff = encode_diff_record(&MnListDiffRecord::build(&a, &b), &NET).expect("diff");
        let len = u16::try_from(snapshot.as_bytes().len()).expect("a small list");
        let mut seed = vec![5u8];
        seed.extend_from_slice(&len.to_le_bytes());
        seed.extend_from_slice(snapshot.as_bytes());
        seed.extend_from_slice(diff.as_bytes());
        let path = format!("{dir}/apply-{from}-to-{to}");
        if std::env::var_os("DASH_DML_WRITE_SEEDS").is_some() {
            std::fs::write(&path, &seed).expect("write the seed");
        } else {
            assert_eq!(std::fs::read(&path).expect(&path), seed, "{path} is stale");
        }
    }
}

/// The record seeds of node-fuzz's `dml_codec_roundtrip` decode (they start the farm inside the
/// record reader).
#[test]
fn fuzz_record_seeds_decode() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../node-fuzz/seeds/dml_codec_roundtrip");
    let mut seen = 0;
    for entry in std::fs::read_dir(dir).expect("seeds") {
        let path = entry.expect("entry").path();
        if path.file_name().is_some_and(|n| n.to_string_lossy().starts_with("record-")) {
            let bytes = std::fs::read(&path).expect("seed");
            decode_record(&bytes[1..], &NET).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
            seen += 1;
        }
    }
    assert_eq!(seen, 5);
}

/// Full-size imported lists (EV2a's PLAN acceptance, run by hand): `DASH_DML_CORE_LISTS` names
/// a file of `<evodb list hex> ok <canonical hex> <CanonicalMNListHash> <evodb after reload>`
/// lines, the probe's `s3` answers (`contrib/node/ev2a-codec-probe`) on dml-listdiff-check.py
/// samples of the mainnet oracle.
#[test]
#[ignore = "needs DASH_DML_CORE_LISTS"]
#[allow(clippy::disallowed_methods, reason = "the environment names the input file")]
fn imported_lists_match_core_at_full_size() {
    let path = std::env::var("DASH_DML_CORE_LISTS").expect("DASH_DML_CORE_LISTS");
    let text = std::fs::read_to_string(path).expect("lists");
    let mut checked = 0;
    for line in text.lines() {
        let f: Vec<&str> = line.split(' ').collect();
        assert_eq!(f[1], "ok");
        let imported = core_disk::decode_list_s3(&mut unhex(f[0]).as_slice()).expect("evodb list");
        let bytes = unhex(f[2]);
        assert_eq!(canonical(&imported), bytes, "canonical bytes");
        assert_eq!(hex(canonical_mn_list_hash(&imported).as_bytes()), f[3], "hash");
        let decoded = decode_list(&bytes);
        assert!(decoded.is_equal(&imported));
        assert_eq!(&*imported.core_order(), evodb_order(&unhex(f[4])).as_slice(), "reload order");
        checked += 1;
    }
    println!("{checked} imported lists match Core");
}

// ----------------------------------------------------------------------------------------------
// The Domain first-entry vectors (R7; SW-V24 rc.4 audit §4.3, DEC-456 (2), DEC-461).

/// The IPv4 service 1.1.1.1:9999 as an `ExtNetInfo` entry.
const SERVICE_ENTRY: [u8; 9] = [0x01, 0x01, 0x04, 1, 1, 1, 1, 0x27, 0x0f];

/// A Domain entry: type 0x02, `claimed` as the name's CompactSize length, then `body` (the name
/// and its big-endian port, or less).
fn domain_entry(claimed: u64, body: &[u8]) -> Vec<u8> {
    [&[2u8][..], &compact(claimed), body].concat()
}

/// A Domain entry holding `name` and port 443 in full.
fn full_domain(name: &str) -> Vec<u8> {
    domain_entry(name.len() as u64, &[name.as_bytes(), &443u16.to_be_bytes()].concat())
}

/// An `ExtNetInfo` of one Core P2P group holding `entries`; its first entry starts at byte 4
/// (version, group count, purpose, entry count).
fn core_p2p_group(entries: &[Vec<u8>]) -> Vec<u8> {
    [&[1u8, 1, 0, entries.len() as u8][..], &entries.concat()].concat()
}

fn read_net_info(bytes: &[u8]) -> (Result<NetInfo, CodecError>, usize) {
    let mut input = bytes;
    let read = Reader::new(&mut input, None).net_info(true);
    (read, input.len())
}

/// D1-D4: a Domain body that is oversized, claims a huge length, or ends early fails the read
/// at the first entry (`NetInfoEntry::Unserialize`, `netinfo.h` rc.4:243-263; `LIMITED_STRING`
/// throws above `DOMAIN_MAX_LEN` before allocating): the error names its offset, and the reader
/// stops inside it, so a second entry is never read. The same at rc.3.
#[test]
fn a_bad_domain_body_fails_at_the_first_entry() {
    let rows = [
        (
            "D1",
            domain_entry(254, &[&[b'a'; 254][..], &[1, 0xbb]].concat()),
            Some(&SERVICE_ENTRY[..]),
        ),
        ("D2", domain_entry(0xffff, b"abc"), None),
        ("D3", domain_entry(20, &[b'a'; 10]), None),
        ("D4", domain_entry(11, &[&b"example.com"[..], &[1]].concat()), None),
    ];
    for (name, first, second) in rows {
        let entries: Vec<Vec<u8>> =
            [Some(first.clone()), second.map(<[u8]>::to_vec)].into_iter().flatten().collect();
        let bytes = core_p2p_group(&entries);
        let (read, left) = read_net_info(&bytes);
        let e = read.expect_err(name);
        assert!(e.0.starts_with("net info: the entry at byte 4: "), "{name}: {e}");
        // Stopped inside the first entry: its own bytes, and all of the second, remain.
        let first_rest = bytes.len() - 4 - first.len();
        assert!(left > first_rest, "{name}: {left} bytes left");
        if let Some(second) = second {
            assert!(bytes.ends_with(second) && left >= second.len(), "{name}");
        }
    }
}

/// D5, D6 and the control D5b: a Domain body that reads fully, and an unknown entry type, do not
/// fail the read. D5's "a..b" (an empty label, `BadLabelLen`) and D6's type 0x07 read as the
/// invalid entry and the second entry is read; D5b's "a.b" is a valid domain (`DOMAIN_MIN_LEN` =
/// 3, `netinfo.cpp` rc.4:24, 90-113) and is kept.
#[test]
fn a_domain_that_reads_fully_does_not_fail_the_read() {
    let service = NIEntry::decode(&mut &SERVICE_ENTRY[..]).expect("a service");
    let rows: [(&str, Vec<u8>, bool); 3] = [
        ("D5", full_domain("a..b"), false),
        ("D5b", full_domain("a.b"), true),
        ("D6", vec![0x07], false),
    ];
    for (name, first, kept) in rows {
        let bytes = core_p2p_group(&[first, SERVICE_ENTRY.to_vec()]);
        let (read, left) = read_net_info(&bytes);
        assert_eq!(left, 0, "{name}");
        let NetInfo::Extended(v2) = read.expect(name) else {
            panic!("{name}: not extended");
        };
        let [(NIPurpose::CoreP2p, group)] = &v2.entries[..] else {
            panic!("{name}: {v2:?}");
        };
        assert_eq!(group.len(), 2, "{name}");
        assert_eq!(group[0] != NIEntry::Invalid, kept, "{name}: {:?}", group[0]);
        assert_eq!(group[1], service, "{name}");
    }
}

/// CE4-01 on the record reader: a repeated or descending purpose fails the read at that purpose,
/// before its group (`netinfo.h` rc.4:419-437), with Core's text. rc.3 read the first as one group
/// and the second in map order.
#[test]
fn records_read_purposes_strictly() {
    let svc = SERVICE_ENTRY.to_vec();
    let five: Vec<u8> = (0..5).flat_map(|_| svc.clone()).collect();
    // (name, bytes, the offset just past the bad purpose byte)
    for (name, bytes, stop) in [
        ("repeated", [&[1u8, 2, 0, 1][..], &svc, &[0, 1], &svc].concat(), 4 + 9 + 1),
        ("descending", [&[1u8, 2, 1, 5][..], &five, &[0, 1], &svc].concat(), 4 + 45 + 1),
        ("unknown", [&[1u8, 1, 3, 1][..], &svc].concat(), 3),
    ] {
        let (read, left) = read_net_info(&bytes);
        assert_eq!(
            read.expect_err(name).0,
            "ExtNetInfo: purpose unknown or out of order",
            "{name}"
        );
        assert_eq!(bytes.len() - left, stop, "{name}: read past the bad purpose");
        assert!(
            matches!(NetInfoV2::decode(&mut &bytes[..]), Err(DecodeError::InvalidValue { .. })),
            "{name}: base-sdk reads the purposes"
        );
    }
    let ok = [&[1u8, 2, 0, 1][..], &svc, &[2, 1], &svc].concat();
    assert_eq!(read_net_info(&ok).1, 0);
}
